export function safeGitState(raw){const s={passed:{},quiz:{},completed:{},positions:{},quizPositions:{},drafts:{},last:null,saved:false,savedRevision:null};if(!raw||typeof raw!=='object'||Array.isArray(raw))return s;const lesson=id=>/^git-m[1-4]-0[1-3]$/.test(id),activity=id=>/^git-m[1-4]-0[1-3]-a[1-4]$/.test(id);for(const key of ['passed','completed','positions','quizPositions','quiz','drafts'])for(const [id,v]of Object.entries(raw[key]||{}).slice(0,200)){if(key==='passed'&&activity(id)&&v===true)s.passed[id]=true;else if(key==='completed'&&lesson(id)&&v===true)s.completed[id]=true;else if(['positions','quizPositions'].includes(key)&&lesson(id)&&Number.isInteger(v))s[key][id]=Math.max(0,Math.min(key==='positions'?3:2,v));else if(key==='quiz'&&/^git-m[1-4]-0[1-3]-q[1-3]$/.test(id))s.quiz[id]={value:Number.isInteger(v?.value)?Math.max(0,Math.min(5,v.value)):null,checked:v?.checked===true,correct:v?.checked===true&&v?.correct===true};else if(key==='drafts'&&activity(id)&&v&&typeof v==='object')s.drafts[id]={path:String(v.path||'notes.txt').slice(0,160),text:String(v.text||'').slice(0,20000),branch:String(v.branch||'idee').slice(0,40),message:String(v.message||'').slice(0,120),answer:Number.isInteger(v.answer)?Math.max(0,Math.min(5,v.answer)):null}}if(lesson(raw.last))s.last=raw.last;s.saved=raw.saved===true;s.savedRevision=/^[a-f0-9]{12}$/.test(raw.savedRevision)?raw.savedRevision:null;return s}
